-- doodles-beachfront-restaurant-bloubergstrand (researched)
UPDATE businesses SET description = 'Doodles Beachfront is a restaurant and function venue on the beachfront in Bloubergstrand, with panoramic views of Table Mountain and the bay. The sun sets beyond Robben Island, and the enclosed lower deck makes outdoor dining comfortable in all weather.

The menu includes an a la carte selection, a snack platter menu and a pensioners menu, along with an extensive wine list. The venue has live music, and the business says it offers set menus and platter options for private functions.

The kitchen serves breakfast, lunch, light meals and dinner, and the team says the setting, live music and service combine into a memorable evening.

It suits groups and families who want a lively meal with a view across the bay in Bloubergstrand.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://doodles.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'doodles-beachfront-restaurant-bloubergstrand' AND description = 'Doodles Beachfront Restaurant is a family-friendly restaurant in Bloubergstrand open since 1991, serving seafood, steaks and pizzas with panoramic views of Table Mountain and the Atlantic Ocean, plus an indoor play area for children.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
